inline const Pass* FindPass(uint32_t key) {
  const auto it = std::lower_bound(kPasses.begin(), kPasses.end(), key,
                                   [](const Pass& p, uint32_t k) { return p.key < k; });
  return it != kPasses.end() && it->key == key ? &*it : nullptr;
}

